2. Crea un componente de filtro en React que contenga campos de entrada para establecer el rango de fechas y el nivel de gravedad.

```
import React from 'react';
import { Form } from 'react-bootstrap';

const CrimeFilters = (props) => {
  const handleDateRangeChange = (event) => {
    const { name, value } = event.target;
    setDateRange({ ...dateRange, [name]: value });
  };

  const handleSeverityChange = (event) => {
    setSeverity(event.target.value);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    props.onFilterChange(dateRange, severity); // Pasa los parámetros de filtro al componente principal
  };

  return (
    <Form onSubmit={handleSubmit}>
      <Form.Group controlId="formDateStart">
        <Form.Label>Rango de fechas (Inicio)</Form.Label>
        <Form.Control
          type="date"
          name="start"
          value={dateRange.start}
          onChange={handleDateRangeChange}
        />
      </Form.Group>
      <Form.Group controlId="formDateEnd">
        <Form.Label>Rango de fechas (Fin)</Form.Label>
        <Form.Control
          type="date"
          name="end"
          value={dateRange.end}
          onChange={handleDateRangeChange}
        />
      </Form.Group>
      <Form.Group controlId="formSeverity">
        <Form.Label>Nivel de gravedad</Form.Label>
        <Form.Control
          as="select"
          value={severity}
          onChange={handleSeverityChange}
        >
          <option value="">Todos</option>
          <option value="Alto">Alto</option>
          <option value="Medio">Medio</option>
          <option value="Bajo">Bajo</option>
        </Form.Control>
      </Form.Group>
      <Button variant="primary" type="submit">
        Aplicar filtros
      </Button>
    </Form>
  );
};

