        xhr.open("GET", `/download/${file.name}`);
        xhr.responseType = "blob";
        xhr.onerror = () => {
          const placeholderImage = new Image();
          placeholderImage.src = "placeholder.png";
          placeholderImage.onload = () => {
            const canvas = document.createElement("canvas");
            canvas.width = placeholderImage.width;
            canvas.height = placeholderImage.height;
            const ctx = canvas.getContext("2d");
            ctx.drawImage(placeholderImage, 0, 0);
            const dataURL = canvas.toDataURL();
            file.url = dataURL;
            resolve(`No se pudo descargar el archivo ${file.name}. Usando marcador de posición.`);
          };
        };
        xhr.onload = () => {
          if (xhr.status === 200) {
            const blobURL = URL.createObjectURL(xhr.response);
            file.url = blobURL;
            resolve(`Archivo ${file.name} descargado con éxito`);
          } else {
            const placeholderImage = new Image();
            placeholderImage.src = "placeholder.png";
            placeholderImage.onload = () => {
              const canvas = document.createElement("canvas");
              canvas.width = placeholderImage.width;
              canvas.height = placeholderImage.height;
              const ctx = canvas.getContext("2d");
              ctx.drawImage(placeholderImage, 0, 0);
              const dataURL = canvas.toDataURL();
              file.url = dataURL;
              reject(`Error al descargar el archivo ${file.name}. Usando marcador de posición.`);
            };
          }
        };
        xhr.send();
      }));
    }
    return Promise.all(promises);
  }

  addFile(file) {
    this.files.push(file);
  }

  removeFile(file) {
    const index = this.files.indexOf(file);
    if (index > -1) {
      this.files.splice(index, 1);
    }
  }
